@@ -1049,1 +1050,0 @@
-    Label loop_forward, loop_backward, done;
@@ -1051,21 +1051,5 @@
-    __ mv(dst, d);
-    __ mv(src, s);
-    __ mv(cnt, count);
-
-    __ bind(loop_forward);
-    __ vsetvli(vl, cnt, sew, lmul);
-    if (is_backward) {
-      __ bne(vl, cnt, loop_backward);
-    }
-
-    __ vlex_v(v0, src, sew);
-    __ sub(cnt, cnt, vl);
-    if (sew != Assembler::e8) {
-      // when sew == e8 (e.g., elem size is 1 byte), slli R, R, 0 is a nop and unnecessary
-      __ slli(vl, vl, sew);
-    }
-    __ add(src, src, vl);
-
-    __ vsex_v(v0, dst, sew);
-    __ add(dst, dst, vl);
-    __ bnez(cnt, loop_forward);
+    if (is_forward) {
+      Label loop;
+      __ mv(dst, d);
+      __ mv(src, s);
+      __ mv(cnt, count);
@@ -1073,2 +1057,11 @@
-    if (is_backward) {
-      __ j(done);
+      __ bind(loop);
+      __ vsetvli(vl, cnt, sew, lmul);
+      __ vlex_v(v0, src, sew);
+      __ sub(cnt, cnt, vl);
+      __ shift_left_add(src, vl, src, sew, t0);
+      __ vsex_v(v0, dst, sew);
+      __ shift_left_add(dst, vl, dst, sew, t0);
+      __ bnez(cnt, loop);
+    } else {
+      Label loop;
+      __ mv(cnt, count);
@@ -1076,10 +1069,2 @@
